namespace sv_6315aeadda6045beb7219af47e706629.Client;

// Serializable DTO used to persist auth state across render modes.
public sealed class UserInfo
{
    public required string Email { get; set; }
    public required string[] Roles { get; set; }
}

using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;

namespace sv_6315aeadda6045beb7219af47e706629.Client;

// Runs on WebAssembly. Reads the auth state that the server persisted
// into PersistentComponentState so identity survives the render-mode switch.
public sealed class PersistentAuthenticationStateProvider : AuthenticationStateProvider
{
    private static readonly Task<AuthenticationState> _unauthenticated =
        Task.FromResult(new AuthenticationState(new ClaimsPrincipal(new ClaimsIdentity())));

    private readonly Task<AuthenticationState> _authenticationStateTask;

    public PersistentAuthenticationStateProvider(PersistentComponentState state)
    {
        if (!state.TryTakeFromJson<UserInfo>(nameof(UserInfo), out var userInfo) || userInfo is null)
        {
            _authenticationStateTask = _unauthenticated;
            return;
        }

        var claims = new List<Claim>
        {
            new(ClaimTypes.Name, userInfo.Email),
            new(ClaimTypes.Email, userInfo.Email),
        };

        foreach (var role in userInfo.Roles)
        {
            claims.Add(new Claim(ClaimTypes.Role, role));
        }

        _authenticationStateTask = Task.FromResult(
            new AuthenticationState(new ClaimsPrincipal(new ClaimsIdentity(claims, "Persistent"))));
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync() =>
        _authenticationStateTask;
}

using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Server;
using Microsoft.AspNetCore.Components.Web;
using sv_6315aeadda6045beb7219af47e706629.Client;

namespace sv_6315aeadda6045beb7219af47e706629;

// Server-side provider that creates a hardcoded identity and persists it
// into PersistentComponentState so the WASM client can pick it up.
public sealed class ServerAuthenticationStateProvider : ServerAuthenticationStateProvider<UserInfo>
{
    private static readonly UserInfo _user = new()
    {
        Email = "bob@example.com",
        Roles = ["User", "Editor"]
    };

    protected override Task<AuthenticationState> GetAuthenticationStateAsync(
        PersistentComponentState persistentComponentState)
    {
        persistentComponentState.RegisterOnPersisting(() =>
        {
            persistentComponentState.PersistAsJson(nameof(UserInfo), _user);
            return Task.CompletedTask;
        }, RenderMode.InteractiveWebAssembly);

        var claims = new List<Claim>
        {
            new(ClaimTypes.Name, _user.Email),
            new(ClaimTypes.Email, _user.Email),
        };

        foreach (var role in _user.Roles)
        {
            claims.Add(new Claim(ClaimTypes.Role, role));
        }

        return Task.FromResult(
            new AuthenticationState(new ClaimsPrincipal(new ClaimsIdentity(claims, "Hardcoded"))));
    }
}

