// Server-side provider that creates a hardcoded identity and persists it
// into PersistentComponentState so the WASM client can pick it up.
public sealed class ServerAuthenticationStateProvider : ServerAuthenticationStateProvider<UserInfo>
{
    private static readonly UserInfo _user = new()
    {
        Email = "bob@example.com",
        Roles = ["User", "Editor"]
    };

    protected override Task<AuthenticationState> GetAuthenticationStateAsync(
        PersistentComponentState persistentComponentState)
    {
        persistentComponentState.RegisterOnPersisting(() =>
        {
            persistentComponentState.PersistAsJson(nameof(UserInfo), _user);
            return Task.CompletedTask;
        }, RenderMode.InteractiveWebAssembly);

        var claims = new List<Claim>
        {
            new(ClaimTypes.Name, _user.Email),
            new(ClaimTypes.Email, _user.Email),
        };

        foreach (var role in _user.Roles)
        {
            claims.Add(new Claim(ClaimTypes.Role, role));
        }

        return Task.FromResult(
            new AuthenticationState(new ClaimsPrincipal(new ClaimsIdentity(claims, "Hardcoded"))));
    }
}

